select jsonb_build_object(
'checked_at_kst',to_char(clock_timestamp() at time zone 'Asia/Seoul','YYYY-MM-DD HH24:MI:SS'),
'data',(select jsonb_agg(to_jsonb(d) order by name) from (select 'profiles' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.profiles t) x union all select 'student_applications' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.student_applications t) x union all select 'student_application_events' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.student_application_events t) x union all select 'study_sessions' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.study_sessions t) x union all select 'mock_exam_attempts' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.mock_exam_attempts t) x union all select 'mock_exam_answers' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.mock_exam_answers t) x union all select 'day_targets' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.day_targets t) x union all select 'account_deletion_requests' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.account_deletion_requests t) x union all select 'universities' name,count(*) rows,md5(coalesce(string_agg(h,'' order by h),'')) digest from (select md5(to_jsonb(t)::text) h from public.universities t) x) d),
'functions',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(s,'|' order by s))) from (select p.oid::regprocedure::text||'|'||pg_get_functiondef(p.oid)||'|'||coalesce(p.proacl::text,'') s from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (n.nspname='public' or n.nspname like '%\_private' escape '\') and p.prokind in ('f','p') and not(n.nspname='public' and p.proname in ('my_home_configuration','save_my_home_configuration'))) f),
'policies',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(to_jsonb(p)::text,'|' order by schemaname,tablename,policyname))) from pg_policies p where schemaname='public' and tablename<>'home_configuration_revisions'),
'tables',(select jsonb_build_object('count',count(*),'digest',md5(string_agg(s,'|' order by s))) from (select n.nspname||'.'||c.relname||'|'||c.relrowsecurity::text||'|'||c.relforcerowsecurity::text||'|'||coalesce(c.relacl::text,'') s from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind in ('r','p') and c.relname<>'home_configuration_revisions') t),
'critical_rpcs',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'hash',md5(pg_get_functiondef(p.oid)),'acl',p.proacl::text) order by p.proname) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('my_applications','my_application_save','my_application_event','my_application_events','my_application_delete'))
) as preservation;
